import{_ as e,o as c,c as l,a3 as s}from"./chunks/framework.DdpBa4_E.js";const _=JSON.parse('{"title":"console 篇 - console.log 的 \\"bug\\" ?","description":"","frontmatter":{},"headers":[],"relativePath":"books/chrome-devtools/07-console-篇-console-的-bug.md","filePath":"books/chrome-devtools/07-console-篇-console-的-bug.md","lastUpdated":1781445373000}'),t={name:"books/chrome-devtools/07-console-篇-console-的-bug.md"};function a(n,o,d,p,i,r){return c(),l("div",null,[...o[0]||(o[0]=[s('<h1 id="console-篇-console-log-的-bug" tabindex="-1">console 篇 - console.log 的 &quot;bug&quot; ? <a class="header-anchor" href="#console-篇-console-log-的-bug" aria-label="Permalink to &quot;console 篇 - console.log 的 &quot;bug&quot; ?&quot;">​</a></h1><p>一般来说，我们会使用 <code>console.log()</code> 来打印某个对象，并且，两次打印之间，还会对这个对象进行修改，最后我们查看打印的结果发现，修改前的打印和修改后的打印，竟然是一样的？这样出乎意料的情况，让我们难以继续 <code>console.log</code> 的调试。</p><p>口说无凭，举个例子把：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/11/1679a0d3a708ef3e~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p>我们可以看到，一共有两次打印，一次是打印原始信息，一次是打印我们修改后的信息，并且我们把属性 <code>a</code> 从 <code>0</code> 改成 <code>1</code> ，<code>name</code> 属性从 <code>Tomek</code> 改成 <code>Not Tomek</code></p><p>但打印的时候，两次都是我们修改之后的值？</p><p>那，为什么会出现这一现象？</p><p>说明：</p><blockquote><p><code>console</code> 中打印出的对象，在你打印出他内容之前，是以引用的方式保存的。</p></blockquote><p>知道了原因，对应的就知道该怎么处理这样的情况了：</p><ul><li>打印一个从这个对象复制出来的对象。</li><li>使用资源面中的断点来调试</li><li>使用 <code>JSON.stringify()</code> 方法处理打印的结果</li><li>更多你可以想到的好方法~</li></ul>',11)])])}const u=e(t,[["render",a]]);export{_ as __pageData,u as default};
